/* Opening snapshots and reviewed manual transfers. Amounts are always toman. */
function confirmedPayments(){return db.payments.filter(p=>p.status==='approved')}
function remainingDebt(s){return Math.max(0,Number(s.opening_debt)-confirmedPayments().filter(p=>p.student_id===s.id&&p.purpose==='opening_debt').reduce((a,p)=>a+Number(p.amount),0))}
function totalPaid(s){return Number(s.opening_paid||0)+confirmedPayments().filter(p=>p.student_id===s.id).reduce((a,p)=>a+Number(p.amount),0)}
let bankAccount=null;const coreReload=reload;reload=async function(){if(role!=='teacher')bankAccount=(await api('/rest/v1/tuition_bank_account?select=*'))[0]||null;return coreReload()};
const digits=s=>String(s??'').replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));
const paymentStatus=p=>({pending:'در دست بررسی',approved:'تأییدشده',rejected:'ردشده'})[p.status]||p.status;
function bankReady(){return bankAccount?.holder&&bankAccount?.card&&bankAccount?.iban}
function bankPanel(){return bankReady()?`<div class="card bank-panel"><h3>حساب واریز شهریه</h3><p>صاحب حساب: <strong>${esc(bankAccount.holder)}</strong> · ${esc(bankAccount.bank_name)}</p><div class="bank-number"><span>شماره کارت</span><b dir="ltr">${esc(bankAccount.card.match(/.{1,4}/g).join(' '))}</b><button onclick="copyBank('card')">کپی کارت</button></div><div class="bank-number"><span>شماره شبا</span><b dir="ltr">${esc(bankAccount.iban)}</b><button onclick="copyBank('iban')">کپی شبا</button></div><p>${esc(bankAccount.instructions)}</p><p class="sub">همهٔ مبالغ پرتال تومان است؛ اگر برنامهٔ بانک ریال می‌خواهد، مبلغ را ×۱۰ کنید.</p></div>`:`<div class="card policy"><h3>حساب بانکی هنوز تکمیل نشده است</h3><p>${admin?'ابتدا «تنظیم حساب واریز» را تکمیل کنید.':'برای مشخصات واریز با دفتر هماهنگ کنید؛ ثبت رسید پس از تکمیل حساب فعال می‌شود.'}</p></div>`}
async function copyBank(key){try{await navigator.clipboard.writeText(bankAccount[key]);toast('کپی شد')}catch{toast('شماره را از روی صفحه کپی کنید')}}
function configureBank(){if(!admin)return;form('تنظیم حساب واریز شهریه',[field('holder','نام دقیق صاحب حساب'),field('card','شماره کارت ۱۶ رقمی'),field('iban','شبا؛ IR و ۲۴ رقم'),field('bank_name','نام بانک'),field('instructions','توضیحات واریز')],async d=>{d.card=digits(d.card).replace(/[\s-]/g,'');d.iban=digits(d.iban).replace(/[\s-]/g,'').toUpperCase();if(!/^\d{16}$/.test(d.card)||!/^IR\d{24}$/.test(d.iban))throw Error('شماره کارت یا شبا کامل نیست');await api('/rest/v1/tuition_bank_account?id=eq.true','PATCH',{...d,updated_at:new Date().toISOString()})});for(const k of ['holder','card','iban','bank_name','instructions'])$('form').elements[k].value=bankAccount?.[k]||''}
views.payments=function(){return title('شهریه و رسیدهای واریز','فقط پرداخت تأییدشده از بدهی کم می‌شود و اعتبار جلسات ایجاد می‌کند.',office?btn('ثبت دریافت تأییدشده','newPayment()'):'')+(admin?'<p><button onclick="configureBank()">تنظیم حساب واریز</button></p>':'')+bankPanel()+(role==='student'&&db.students[0]?`<div class="card"><h3>پرداخت شهریه</h3><p>مانده بدهی انتقالی: <b>${money(remainingDebt(db.students[0]))} تومان</b> · جلسات باقی‌مانده: ${money(credit(db.students[0]))}</p><button class="primary" onclick="submitTransfer()" ${bankReady()?'':'disabled'}>پرداخت شهریه و ثبت رسید</button></div>`:'')+`<div class="card"><h3>رسیدهای در انتظار: ${money(db.payments.filter(p=>p.status==='pending').length)}</h3>${table(['هنرجو','بابت','مبلغ / تومان','پیگیری و تاریخ واریز','وضعیت','بررسی'],[...db.payments].sort((a,b)=>(a.status==='pending'?-1:1)-(b.status==='pending'?-1:1)||b.created_at.localeCompare(a.created_at)).map(p=>`<tr><td>${esc(full(db.students.find(s=>s.id===p.student_id)||{first_name:'',last_name:''}))}</td><td>${p.purpose==='opening_debt'?'تسویه بدهی انتقالی':money(p.terms)+' ترم'}</td><td>${money(p.amount)}</td><td><b dir="ltr">${esc(p.reference)}</b><br>${esc(p.paid_on)}<small class="sub">${esc(p.payer_note)}</small></td><td><span class="badge ${p.status==='approved'?'':'red'}">${paymentStatus(p)}</span><p>${esc(p.review_note)}</p></td><td>${office&&p.status==='pending'?`<button onclick="reviewTransfer('${p.id}',true)">تأیید واریز</button> <button onclick="reviewTransfer('${p.id}',false)">رد رسید</button>`:p.reviewed_at?new Date(p.reviewed_at).toLocaleDateString('fa-IR'):'منتظر بررسی دفتر'}</td></tr>`))}</div><p class="sub">ثبت شماره پیگیری به معنی تأیید واریز نیست. رسید تأییدشده دوباره قابل تأیید یا حذف نیست.</p>`};
function transferFields(officeMode){let options=officeMode?[['tuition','شهریه یک یا دو ترم'],['opening_debt','تسویه بدهی انتقالی']]:remainingDebt(db.students[0])>0?[['opening_debt','تسویه بدهی انتقالی'],['tuition','شهریه ترم جدید']]:[['tuition','شهریه ترم جدید']];return [...(officeMode?[field('student_id','هنرجو','text',studentsOpt())]:[]),field('purpose','بابت پرداخت','text',options),field('terms','تعداد ترم (فقط شهریه)','text',[[1,'۱ ترم · ۲ میلیون تومان'],[2,'۲ ترم · ۴ میلیون تومان']]),field('amount','مبلغ / تومان','number'),field('reference','شماره پیگیری یکتای رسید'),field('paid_on','تاریخ واریز (میلادی)','date'),field('payer_note','توضیح واریز (اختیاری؛ می‌توانید خط تیره بگذارید)')]}
function bindTransfer(){const f=$('form');f.elements.paid_on.value=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Tehran'});f.elements.payer_note.value='-';function update(){const sid=f.elements.student_id?.value||db.students[0]?.id,s=db.students.find(s=>s.id===sid),isTerm=f.elements.purpose.value==='tuition';f.elements.terms.disabled=!isTerm;f.elements.amount.readOnly=isTerm;f.elements.amount.value=isTerm?Number(f.elements.terms.value)*2000000:remainingDebt(s);$('transfer-total').innerHTML=`<strong>مبلغ واریز: ${money(f.elements.amount.value)} تومان</strong><p>${money(Number(f.elements.amount.value)*10)} ریال</p>`}f.elements.purpose.onchange=update;f.elements.terms.onchange=update;f.elements.student_id?.addEventListener('change',update);f.elements.amount.oninput=()=>{$('transfer-total').textContent=money(f.elements.amount.value)+' تومان · '+money(Number(f.elements.amount.value)*10)+' ریال'};const summary=document.createElement('div');summary.id='transfer-total';summary.className='policy';$('fields').prepend(summary);update();}
async function recordTransfer(d,approved){const sid=office?d.student_id:db.students[0]?.id,s=db.students.find(s=>s.id===sid);if(!s)throw Error('پرونده متصل نیست');const amount=Number(digits(d.amount));if(!Number.isSafeInteger(amount)||amount<=0)throw Error('مبلغ معتبر نیست');if(d.purpose==='opening_debt'&&amount>remainingDebt(s))throw Error('مبلغ بیشتر از بدهی است');const reference=digits(d.reference).trim();if(db.payments.some(p=>p.reference===reference))throw Error('این شماره پیگیری قبلاً ثبت شده است');await api('/rest/v1/payments','POST',{student_id:sid,purpose:d.purpose,terms:d.purpose==='tuition'?Number(d.terms):0,amount,reference,paid_on:d.paid_on,payer_note:d.payer_note,status:approved?'approved':'pending',submitted_by:uid})}
function submitTransfer(){if(role!=='student'||!db.students[0]||!bankReady())return;form('ثبت مشخصات واریز؛ بررسی توسط دفتر',transferFields(false),d=>recordTransfer(d,false));$('form').querySelector('[type=submit]').textContent='ارسال رسید برای بررسی';bindTransfer();const bank=document.createElement('div');bank.style.gridColumn='1/-1';bank.innerHTML=(db.payments.some(p=>p.status==='pending')?'<p class="policy">رسید در دست بررسی دارید؛ برای همان واریز دوباره پول منتقل نکنید. ابتدا منتظر نتیجهٔ بررسی بمانید.</p>':'')+bankPanel()+'<p>۱. مبلغ مشخص‌شده را واریز کنید. ۲. شماره پیگیری رسید بانک را در فرم پایین بنویسید. ۳. منتظر تأیید دفتر بمانید.</p>';$('fields').prepend(bank);}
newPayment=function(){if(!allowed())return;if(!db.students.length){toast('ابتدا هنرجو را ثبت کنید');return}form('ثبت دریافت پس از مشاهده و تأیید واریز',transferFields(true),async d=>{if(!confirm('واریز را در حساب بانکی دیده‌اید؟ تأیید، اثر مالی قطعی دارد.'))throw Error('ثبت لغو شد');await recordTransfer(d,true)});bindTransfer()};
async function reviewTransfer(id,approved){if(!office)return;const p=db.payments.find(p=>p.id===id);if(!p||p.status!=='pending')return;let note='واریز در حساب بررسی و تأیید شد';if(approved){if(!confirm('تأیید دریافت '+money(p.amount)+' تومان با پیگیری '+p.reference+'؟ فقط پس از مشاهده واریز در حساب تأیید کنید.'))return}else{note=prompt('دلیل رد رسید را بنویسید');if(!note||note.trim().length<3)return}try{const result=await api('/rest/v1/payments?id=eq.'+id+'&status=eq.pending','PATCH',{status:approved?'approved':'rejected',review_note:note});if(!result.length)throw Error('رسید قبلاً بررسی شده؛ صفحه را تازه کنید');await reload();toast(approved?'واریز تأیید و مانده به‌روز شد':'رسید با دلیل رد شد')}catch(e){toast(e.message)}}
views.portal=function(){const s=db.students.find(s=>s.user_id===uid);return title('پرتال هنرجو','پرونده، مانده شهریه و وضعیت رسیدها')+(s?`<div class="hero"><div><h2>${esc(full(s))}</h2><p>${esc(s.subject)} · استاد ${esc(teacher(s.teacher_id))} · ${days[s.weekday]} ساعت ${esc(s.class_time.slice(0,5))}</p></div></div><div class="stats">${[['کل پرداخت تأییدشده',money(totalPaid(s))+' تومان'],['از این مبلغ، قبل از انتقال',money(s.opening_paid)+' تومان'],['مانده بدهی انتقالی',money(remainingDebt(s))+' تومان'],['جلسات باقی‌مانده',money(credit(s))+' جلسه']].map(a=>`<div class="card"><div class="sub">${a[0]}</div><h3>${a[1]}</h3></div>`).join('')}</div><div class="card"><h3>${eligible(s)?'مجاز به حضور':'نیازمند پرداخت شهریه'}</h3><p>رسیدهای در دست بررسی: ${money(db.payments.filter(p=>p.student_id===s.id&&p.status==='pending').reduce((a,p)=>a+Number(p.amount),0))} تومان؛ تا تأیید دفتر از بدهی کم نمی‌شود.</p><button class="primary" onclick="go('payments')">پرداخت شهریه و مشاهده رسیدها</button><p>مانده افتتاحیه در تاریخ ${esc(s.balance_date)} ثبت شده است. ${esc(s.opening_note)}</p></div><div class="card"><h3>اطلاعیه‌های من</h3>${db.notices.map(n=>'<p>'+esc(n.message)+'</p>').join('')||'اطلاعیه‌ای ثبت نشده است'}</div>`:'<div class="card empty">پرونده شما هنوز متصل نیست. با همان ایمیلی که مدیر در پرونده ثبت کرده وارد شوید.</div>')};
newStudent=function(){if(!allowed())return;form('ثبت هنرجو و وضعیت شهریه در تاریخ انتقال',[field('first_name','نام'),field('last_name','نام خانوادگی'),field('father_name','نام پدر'),field('national_id','کد ملی ۱۰ رقمی'),field('mobile','موبایل','tel'),field('email','ایمیل فعال‌سازی پرتال هنرجو','email'),field('birth_date','تاریخ تولد (میلادی)','date'),field('home_phone','تلفن منزل (در صورت نبود، خط تیره)'),field('address','آدرس منزل'),field('teacher_id','استاد','text',db.teachers.map(t=>[t.id,t.name.replace(/فروقی/g,'فروغی')])),field('subject','رشته','text',db.teachers[0]?.subjects.map(s=>[s,s])||[]),field('weekday','روز ثابت','text',days.map((d,i)=>[i,d])),field('class_time','ساعت ثابت','time'),field('balance_date','تاریخ انتقال مانده‌ها (میلادی)','date'),field('opening_paid','کل شهریه پرداخت‌شده تا تاریخ انتقال / تومان','number'),field('opening_credit','جلسات پرداخت‌شده باقی‌مانده در تاریخ انتقال','number'),field('opening_debt','بدهی قطعی تا تاریخ انتقال / تومان','number'),field('opening_note','توضیح مانده‌ها یا مرجع دفتر')],async d=>{for(const k of ['national_id','mobile','home_phone'])d[k]=digits(d[k]).trim();d.email=d.email.trim().toLowerCase();for(const k of ['opening_paid','opening_credit','opening_debt']){d[k]=Number(digits(d[k]));if(!Number.isSafeInteger(d[k])||d[k]<0)throw Error('مانده‌ها باید عدد صحیح و غیرمنفی باشند')}validateStudent(d);if(!confirm('اطلاعات و مانده‌ها بررسی شده‌اند؟ پرداخت‌های قدیمی فقط سابقه‌اند و دوباره اعتبار جلسه ایجاد نمی‌کنند.'))throw Error('ثبت لغو شد');await api('/rest/v1/students','POST',d)});const f=$('form');f.elements.balance_date.value=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Tehran'});for(const k of ['opening_paid','opening_credit','opening_debt'])f.elements[k].value=0;f.elements.opening_note.value='انتقال از دفتر آموزشگاه';f.elements.home_phone.value='-';f.elements.teacher_id.onchange=()=>{const t=db.teachers.find(t=>t.id===f.elements.teacher_id.value);f.elements.subject.innerHTML=t.subjects.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')};const help=document.createElement('p');help.className='policy';help.textContent='تمام مبالغ تومان است. فقط جلسات باقی‌مانده را وارد کنید، نه کل جلسات گذشته. ایمیل، کلید اتصال خودکار حساب هنرجو است. مانده‌ها پس از ثبت مستقیم تغییر نمی‌کنند؛ قبل از تأیید بررسی کنید.';$('fields').prepend(help)};
studentDetail=function(id){if(!office)return;const s=db.students.find(s=>s.id===id);$('mtitle').textContent='پرونده '+full(s);$('error').textContent='';$('fields').innerHTML=`<div class="policy"><p>کد ملی: ${esc(s.national_id)} · موبایل: ${esc(s.mobile)}</p><p>ایمیل ورود: <b dir="ltr">${esc(s.email)}</b></p><p>${s.user_id?'حساب پرتال متصل است':'منتظر فعال‌سازی با ایمیل پرونده'}</p><p>تاریخ تولد: ${esc(s.birth_date)} · نام پدر: ${esc(s.father_name)}</p><p>${esc(s.address)} · تلفن منزل: ${esc(s.home_phone)}</p><p>استاد ${esc(teacher(s.teacher_id))} · ${esc(s.subject)} · ${days[s.weekday]} ${esc(s.class_time.slice(0,5))}</p><hr><p>پرداخت قبلی: ${money(s.opening_paid)} تومان · کل تأییدشده: ${money(totalPaid(s))} تومان</p><p>بدهی اولیه: ${money(s.opening_debt)} · مانده بدهی: ${money(remainingDebt(s))} تومان</p><p>اعتبار باقی‌مانده: ${money(credit(s))} جلسه</p><p>تاریخ انتقال: ${esc(s.balance_date)} · ${esc(s.opening_note)}</p></div>`;$('form').querySelector('[type=submit]').textContent='بستن پرونده';$('form').onsubmit=e=>{e.preventDefault();modal.close()};modal.showModal()};
const originalDashboard=views.dashboard;views.dashboard=function(){return (!bankReady()?'<div class="card policy"><b>قبل از دریافت رسید، حساب بانکی را تنظیم کنید.</b><button onclick="go(\'payments\')">شهریه و تنظیم حساب</button></div>':'')+originalDashboard()+`<div class="card"><h3>واریزهای منتظر بررسی: ${money(db.payments.filter(p=>p.status==='pending').length)}</h3><button onclick="go('payments')">بررسی رسیدهای شهریه</button><p>پرداخت‌های قبل از انتقال جدا از درآمد ثبت‌شده در سامانه نگهداری می‌شوند.</p></div>`};

studentTable=function(list){return table(['هنرجو','رشته و استاد','زمان ثابت','کل پرداخت تأییدشده','بدهی باقی‌مانده','اعتبار','وضعیت','پرونده'],list.map(s=>`<tr><td><b>${esc(full(s))}</b><small class="sub">${esc(s.mobile)}</small></td><td>${esc(s.subject)} · ${esc(teacher(s.teacher_id))}</td><td>${days[s.weekday]} ${esc(s.class_time?.slice(0,5))}</td><td>${money(totalPaid(s))} تومان</td><td>${money(remainingDebt(s))} تومان</td><td>${money(credit(s))} جلسه</td><td>${tag(s)}</td><td><button onclick="studentDetail('${s.id}')">مشاهده</button></td></tr>`))};
